-- ============================================================================
-- Calculadora de Pegada — refinamento: combustão móvel por FROTA (Escopo 1).
-- Até aqui, a combustão móvel usava os fatores de CH4/N2O da combustão
-- estacionária (variáveis por SETOR) como aproximação — o CO2 por combustível
-- é correto, mas CH4/N2O de veículos dependem da TECNOLOGIA (tipo de frota e
-- ano do veículo), não do setor da organização.
--
-- Esta tabela traz as Tabelas 6 (fósseis) e 7 (biocombustíveis) da aba
-- "Fatores de Emissão": CH4 e N2O em kg por litro do combustível COMERCIAL,
-- por tipo de veículo e ano da frota ("all" = "Todos os anos", "2000-" = "até
-- 2000", depois 2001..2025). Emissão = fator × litros / 1000 (toneladas),
-- espelhando a fórmula da planilha (Combustão móvel, colunas AX/AY e BA/BB).
--
-- O CO2 continua vindo de ghg_fuel_factors (correto: é função do combustível).
-- Lançamentos antigos, sem frota informada, seguem usando o fator por setor —
-- a mudança é retrocompatível.
-- ============================================================================

create table ghg_fleet_factors (
  id uuid primary key default gen_random_uuid(),
  fuel_label text,
  vehicle_type text not null,
  year_key text not null,
  ch4_kg_l numeric not null default 0,
  n2o_kg_l numeric not null default 0,
  source text,
  unique (vehicle_type, year_key)
);

alter table ghg_fleet_factors enable row level security;
create policy ghg_fleet_factors_read on ghg_fleet_factors for select to authenticated using (true);

-- ============================================================================
-- Seed de ghg_fleet_factors (CH4/N2O por frota e ano) — gerado por scripts/extract_ghg_factors.py --fleet
-- 348 linhas, 37 tipos de veículo

delete from ghg_fleet_factors;

